package kome.common.data;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lotr.common.LOTRMod;
import net.minecraft.block.Block;
import net.minecraft.init.Blocks;
import net.minecraft.init.Items;
import net.minecraft.item.Item;

/** Curated early-Serf materials grouped by occupation profile, with small faction overrides. */
public final class KOMESerfProfessionCatalog {
    private static final Set<String> ORC=new HashSet<String>(Arrays.asList("mordor","angmar","isengard","dol_guldur","dolguldur","gundabad"));
    private static final Set<String> ELF=new HashSet<String>(Arrays.asList("high_elf","highelf","wood_elf","woodelves","lothlorien"));
    private static final Set<String> SOUTHERN=new HashSet<String>(Arrays.asList("near_harad","nearharad","morwaith","taurethrim","half_troll","halftroll"));
    private KOMESerfProfessionCatalog(){}

    public static List<KOMESerfProfessionAssignment.Candidate> candidatesFor(KOMESerfMaterialProfile profile,String faction){
        if(profile==null)profile=KOMESerfMaterialProfile.GENERAL_LABOR;
        List<KOMESerfProfessionAssignment.Candidate> result=new ArrayList<KOMESerfProfessionAssignment.Candidate>();
        switch(profile){
            case SMITH:add(result,Items.coal,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.iron_ingot,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.copper,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.tin,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.bronze,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.leather,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.string,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addRegionalMetal(result,faction);break;
            case MINING:add(result,Items.coal,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);addBlock(result,Blocks.iron_ore,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,LOTRMod.oreCopper,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,LOTRMod.oreTin,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,LOTRMod.oreSilver,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);addBlock(result,Blocks.gold_ore,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.flint,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.sulfur,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.saltpeter,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.salt,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case BUILDING:addBlock(result,Blocks.cobblestone,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);addBlock(result,Blocks.stone,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);addBlock(result,Blocks.stonebrick,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,LOTRMod.rock,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.brick,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.clay_ball,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.sandstone,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.planks,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,LOTRMod.thatch,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case LUMBER:addBlock(result,Blocks.log,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);addBlock(result,Blocks.planks,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.stick,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,LOTRMod.woodBeamV1,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.sapling,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case FARMING:add(result,Items.wheat,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.wheat_seeds,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.wool,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.hay_block,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.lead,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.carrot,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.potato,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case GROWING:add(result,Items.wheat_seeds,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);addBlock(result,Blocks.sapling,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.red_flower,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.yellow_flower,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.grapeRed,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.grapeWhite,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case BAKING:add(result,Items.wheat,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.sugar,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.egg,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.milk_bucket,0,KOMESerfProfessionAssignment.QuantityTier.NONSTACKABLE);add(result,LOTRMod.salt,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.apple,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case BREWING:add(result,Items.wheat,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.sugar,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.apple,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.grapeRed,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.grapeWhite,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.water_bucket,0,KOMESerfProfessionAssignment.QuantityTier.NONSTACKABLE);add(result,LOTRMod.mug,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);break;
            case HUSBANDRY:add(result,Items.wheat,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.iron_ingot,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.lead,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.salt,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.string,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.saddle,0,KOMESerfProfessionAssignment.QuantityTier.NONSTACKABLE);break;
            case FISHING:addBlock(result,Blocks.planks,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.stick,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.string,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.iron_ingot,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.salt,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.fishing_rod,0,KOMESerfProfessionAssignment.QuantityTier.NONSTACKABLE);break;
            case HUNTING:add(result,Items.stick,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.string,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.arrow,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.feather,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.leather,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.horn,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);break;
            case PRECIOUS_METAL:add(result,Items.coal,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.gold_ingot,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.gold_nugget,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.silver,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.copper,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.pearl,0,KOMESerfProfessionAssignment.QuantityTier.RARE);add(result,LOTRMod.coral,0,KOMESerfProfessionAssignment.QuantityTier.RARE);break;
            case RITUAL:addBlock(result,Blocks.cobblestone,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,LOTRMod.obsidianShard,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.bone,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.glass_bottle,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.red_flower,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.red_mushroom,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.brown_mushroom,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.horn,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);break;
            case SCAVENGING:addBlock(result,Blocks.cobblestone,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.reeds,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.rotten_flesh,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.gemsbokHide,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.gemsbokHorn,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,LOTRMod.horn,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);break;
            case GENERAL_TRADE:case GENERAL_LABOR:addGeneral(result,faction);break;
        }
        if(result.size()<3)addGeneral(result,faction);
        return distinct(result);
    }
    private static void addGeneral(List<KOMESerfProfessionAssignment.Candidate> result,String faction){String key=normalize(faction);if("fangorn".equals(key)){add(result,Items.wheat_seeds,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);addBlock(result,Blocks.sapling,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.red_flower,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.yellow_flower,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);return;}addBlock(result,Blocks.cobblestone,0,KOMESerfProfessionAssignment.QuantityTier.BULK_COMMON);add(result,Items.coal,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.iron_ingot,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.leather,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.string,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.stick,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,Items.clay_ball,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.wool,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);if(ELF.contains(key)){addBlock(result,Blocks.sapling,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);addBlock(result,Blocks.red_flower,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);}if(SOUTHERN.contains(key)){add(result,LOTRMod.fur,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);add(result,LOTRMod.horn,0,KOMESerfProfessionAssignment.QuantityTier.UNCOMMON);add(result,Items.reeds,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD);}if(ORC.contains(key))addRegionalMetal(result,key);}
    static String fallbackKind(String faction){String key=normalize(faction);if("fangorn".equals(key))return "botanical";if(ORC.contains(key))return "orc_industrial";if(ELF.contains(key))return "elven";if(SOUTHERN.contains(key))return "southern";return "general";}
    private static void addRegionalMetal(List<KOMESerfProfessionAssignment.Candidate> result,String faction){String key=normalize(faction);Item item=null;if("isengard".equals(key))item=LOTRMod.urukSteel;else if("durins_folk".equals(key)||"durinsfolk".equals(key))item=LOTRMod.dwarfSteel;else if("blue_mountains".equals(key)||"bluemountains".equals(key))item=LOTRMod.blueDwarfSteel;else if(ELF.contains(key))item=LOTRMod.elfSteel;else if("rhudel".equals(key)||"rhun".equals(key))item=LOTRMod.gildedIron;else if(ORC.contains(key))item=LOTRMod.orcSteel;if(item!=null)add(result,item,0,KOMESerfProfessionAssignment.QuantityTier.REGIONAL_METAL);}
    private static void add(List<KOMESerfProfessionAssignment.Candidate> result,Item item,int damage,KOMESerfProfessionAssignment.QuantityTier tier){if(item!=null)result.add(KOMESerfProfessionAssignment.Candidate.runtime(item,damage,tier));}
    private static void addBlock(List<KOMESerfProfessionAssignment.Candidate> result,Block block,int damage,KOMESerfProfessionAssignment.QuantityTier tier){if(block!=null)add(result,Item.getItemFromBlock(block),damage,tier);}
    private static List<KOMESerfProfessionAssignment.Candidate> distinct(List<KOMESerfProfessionAssignment.Candidate> values){List<KOMESerfProfessionAssignment.Candidate> result=new ArrayList<KOMESerfProfessionAssignment.Candidate>();for(KOMESerfProfessionAssignment.Candidate value:values){boolean found=false;for(KOMESerfProfessionAssignment.Candidate old:result)if(old.key.equals(value.key)&&old.damage==value.damage){found=true;break;}if(!found)result.add(value);}return result;}
    private static String normalize(String value){return value==null?"":value.trim().toLowerCase();}
}
